<?php
class LoginAdminAlert
{
    public static function enqueue(int $userId,string $method): void{
        try{require_once __DIR__.'/AccountAlertLocation.php';$ip=AccountAlertLocation::capture();$event=bin2hex(random_bytes(16));$db=Database::getInstance();$db->transaction(function()use($db,$event,$userId,$method,$ip){$s=$db->getConnection()->prepare("INSERT INTO login_admin_alerts(event_id,user_id,recipient,login_method,occurred_at,updated_at) VALUES(?,?,?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP())");$s->execute([$event,$userId,'tourfectoai@gmail.com',mb_substr($method,0,30)]);if(!(new QueueManager($db))->push(SendLoginAdminAlertJob::class,['event_id'=>$event,'request_ip'=>$ip],'email'))throw new RuntimeException('Login alert queue unavailable');});}
        catch(Throwable $e){Logger::warning('Login admin alert not queued',['user_id'=>$userId]);}
    }
    public static function body(array $user,array $alert,array $location=[]): string{$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$rows=['اسم العميل'=>trim(($user['first_name']??'').' '.($user['last_name']??'')),'الشركة'=>$user['company_name']??'','البريد'=>$user['email']??'','رقم الحساب'=>$user['id']??'','وقت الدخول (UTC)'=>$alert['occurred_at'],'طريقة الدخول'=>$alert['login_method']==='password'?'بريد وكلمة مرور (بعد التحقق بخطوتين إذا كان مفعّلًا)':$alert['login_method']];$rows+=['عنوان IP'=>$location['ip']??'غير متاح','المدينة التقريبية'=>$location['city']??'غير متاحة','البلد التقريبي'=>$location['country']??'غير متاح'];$html='<div dir="rtl"><h2>تسجيل دخول ناجح على Tourfecto.pro</h2><table>';foreach($rows as $label=>$value)$html.='<tr><th style="text-align:right;padding:8px">'.$e($label).'</th><td style="padding:8px">'.$e($value).'</td></tr>';return $html.'</table><p>الموقع الجغرافي تقريبي من عنوان IP وقد يعكس VPN أو شبكة الاتصال.</p><p><a href="https://tourfecto.pro/admin">فتح لوحة الإدارة</a></p></div>';}
    public static function send(string $event,string $requestIp=''): void{
        if(!preg_match('/^[a-f0-9]{32}$/D',$event))return;$pdo=Database::getInstance()->getConnection();$s=$pdo->prepare("UPDATE login_admin_alerts SET status='sending',updated_at=UTC_TIMESTAMP() WHERE event_id=? AND status='queued'");$s->execute([$event]);if(!$s->rowCount())return;$state='uncertain';$error=null;
        try{require_once __DIR__.'/AccountAlertLocation.php';$location=AccountAlertLocation::lookup($requestIp);$s=$pdo->prepare('SELECT * FROM login_admin_alerts WHERE event_id=?');$s->execute([$event]);$alert=$s->fetch(PDO::FETCH_ASSOC);$user=(new User())->find((int)$alert['user_id']);if(!$user)throw new RuntimeException('User unavailable');$res=(new Mailer())->send($alert['recipient'],'Tourfecto','تسجيل دخول ناجح على Tourfecto.pro',self::body($user->toArray(),$alert,$location));$state=!empty($res['success'])?'sent':'failed';if($state==='failed')$error='SMTP did not confirm sending; review the mail log before resending.';}
        catch(Throwable $e){$error='Sending outcome uncertain; review the mail log before resending.';}
        $s=$pdo->prepare('UPDATE login_admin_alerts SET status=?,error_message=?,sent_at=?,updated_at=UTC_TIMESTAMP() WHERE event_id=?');$s->execute([$state,$error,$state==='sent'?gmdate('Y-m-d H:i:s'):null,$event]);
    }
}
